svg.script:
(function(){
var $=function(i){return document.getElementById(i)};
var Y=31557600,P=[1,3*86400,1000*Y],L=[100*Y,1e6*Y,1e9*Y],BD=1e15*Y;
var CX=[170,450,730],CY=190,R=100,MAXE=22,LIM=15,X0=150,X1=750;
var e=0,el=0,ph=[0,0,0],last=null,drag=false,note=0;
var d=[$('d0'),$('d1'),$('d2')],b=[$('b0'),$('b1'),$('b2')],c=[$('c0'),$('c1'),$('c2')],l=[$('l0'),$('l1'),$('l2')];
var U=[[1,'s'],[60,'min'],[3600,'h'],[86400,'d'],[Y,'y'],[Y*1e3,'ky'],[Y*1e6,'My'],[Y*1e9,'Gy'],[Y*1e12,'Ty'],[Y*1e15,'Py']];
function dur(s){
 var i=0;while(i<U.length-1&&s>=U[i+1][0])i++;
 var v=s/U[i][0];
 return (v>=100?Math.round(v):v>=10?v.toFixed(1):v.toFixed(2))+' '+U[i][1];
}
function sup(n){return String(n).replace(/\d/g,function(x){return '⁰¹²³⁴⁵⁶⁷⁸⁹'[x]});}
function num(n){
 if(n<1e6)return Math.floor(n).toLocaleString('en-US');
 var x=Math.floor(Math.log10(n)),m=n/Math.pow(10,x);
 if(m.toFixed(2)==='10.00'){m=1;x++;}
 return m.toFixed(2)+'×10'+sup(x);
}
function draw(t){
 var s=Math.pow(10,e);
 $('knob').setAttribute('cx',X0+(X1-X0)*e/MAXE);
 $('read').textContent=dur(s)+' / s';
 $('el').textContent=dur(el);
 $('note').textContent=t<note?'Black dwarf. Time reset.':'';
 for(var i=0;i<3;i++){
  var blurred=s/P[i]>LIM,life=el>=L[i];
  b[i].style.display=blurred?'':'none';
  d[i].style.display=blurred?'none':'';
  if(!blurred){var a=ph[i]*2*Math.PI-Math.PI/2;
   d[i].setAttribute('cx',CX[i]+R*Math.cos(a));d[i].setAttribute('cy',CY+R*Math.sin(a));}
  c[i].textContent=num(life?el/L[i]:el/P[i]);
  l[i].textContent=life?'lifetimes':'cycles';
 }
}
function tick(t){
 if(last!==null){
  var dt=Math.min((t-last)/1000,0.1),s=Math.pow(10,e);
  el+=dt*s;
  for(var i=0;i<3;i++)if(s/P[i]<=LIM)ph[i]=(ph[i]+dt*s/P[i])%1;
  if(el>=BD){el=0;ph=[0,0,0];note=t+2500;}
 }
 last=t;draw(t);requestAnimationFrame(tick);
}
function set(ev){
 var r=svg.getBoundingClientRect(),x=(ev.clientX-r.left)*900/r.width;
 e=Math.max(0,Math.min(MAXE,(x-X0)/(X1-X0)*MAXE));
}
var k=$('knob'),svg=k.ownerSVGElement;
k.addEventListener('pointerdown',function(ev){drag=true;k.setPointerCapture(ev.pointerId);});
k.addEventListener('pointermove',function(ev){if(drag)set(ev);});
k.addEventListener('pointerup',function(){drag=false;});
svg.addEventListener('pointerdown',function(ev){if(ev.target!==k)set(ev);});
k.addEventListener('keydown',function(ev){
 if(ev.key==='ArrowRight'||ev.key==='ArrowUp')e=Math.min(MAXE,e+0.25);
 else if(ev.key==='ArrowLeft'||ev.key==='ArrowDown')e=Math.max(0,e-0.25);
});
draw(0);requestAnimationFrame(tick);
})();
